### Instruction:
Implement the Quick Sort algorithm with a list of numbers.

### Input:
[2, 5, 4, 1, 6, 2, 9, 3]

### Response:
def quicksort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr)//2]
    left, right, equal = [], [], []
    for x in arr:
        if x < pivot:
            left.append(x)
        elif x > pivot:
            right.append(x)
        else:
            equal.append(x)
    return quicksort(left) + equal + quicksort(right)

