### Instruction:
Create a sorting algorithm to quickly sort an array of integers

### Input:
Array: [5, 4, 6, 7, 1]

### Response:
function quickSort(arr) {
  if (arr.length <= 1) { 
    return arr;
  }
  let pivot = arr.pop();
  let left = [];
  let right = [];

  for (let i = 0; i < arr.length; i++) {
    if (arr[i] < pivot) {
      left.push(arr[i]);
    } else {
      right.push(arr[i]);
    }
  }
  return quickSort(left).concat([pivot], quickSort(right));
}

console.log(quickSort([5, 4, 6, 7, 1])); // [1, 4, 5, 6, 7]

