Create a method in Python to generate all the prime numbers between 1 and 100.

### Response:
def prime_generator(n):
    primes = []
    for i in range(2, n+1):
        is_prime = True
        for j in range(2, i):
            if i%j == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)
    return primes

print(prime_generator(100))

