### Input:
Given List: [1, 4, 2, 9, 5]
Target number: 7

### Response:
def find_pairs_sum(numbers, target):
    res = [] 
    for i in range(len(numbers)): 
        for j in range(i + 1, len(numbers)):
            if numbers[i] + numbers[j] == target: 
                res.append([numbers[i], numbers[j]]) 

    return res

